  const deviceType = normalizeDevice(device);
  const theme = findThemeByEnName(deviceType, themeIdOrName);
  const {
    light,
    dark,
    extra
  } = theme.css;
  styleSheet.textContent = light;
  darkStyleSheet.textContent = dark;
  extraStyleSheet.textContent = extra;
